function sv4_event(array$u,string$a,?int$c,string$t,$id,string$d,array$m=[]):void{try{db_execute('INSERT INTO SafetyVote_AuditLogs(CampaignID,ActorEmployeeID,ActorRole,Action,TargetType,TargetID,BoundedDetail,MetadataJson) VALUES(?,?,?,?,?,?,?,?)',[$c,sv_actor($u),strtoupper((string)($u['role']??'')),$a,$t,(string)$id,sv3_text($d,1000),json_encode($m)]);}catch(Throwable$e){}}
function sv4_campaign(int$id):?array{return db_row('SELECT c.*,v.VersionNo,v.CampaignType,v.PrivacyMode,v.TitleTh,v.TitleEn,v.Summary,v.Description,v.RulesText,v.ResultVisibility,v.PrivacyThreshold,v.ScoringMethod,v.ScoringConfigJson,v.QuorumRuleJson,v.TieBreakRule,v.Status VersionStatus,v.RowVersion VersionRowVersion FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE c.id=?',[$id]);}function sv4_role(array$c,string$emp,string$role,?int$stage):bool{return(bool)db_row('SELECT id FROM SafetyVote_CampaignRoles WHERE CampaignVersionID=? AND EmployeeID=? AND CampaignRole=? AND IsActive=1 AND (StageID IS NULL OR StageID=?) LIMIT 1',[$c['CurrentVersionID'],$emp,$role,$stage]);}
