 if($calc&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_RESULT_VIEW');$c=sv4_campaign((int)$calc['id']);$stage=sv3_int(json_body()['stageId']??null);if(!$c||!$stage)json_response(['success'=>false,'code'=>'VALIDATION_FAILED'],400);$out=sv4_calculate(sv4_result_input($c,$stage));$n=db_row('SELECT COALESCE(MAX(SnapshotNo),0)+1 no FROM SafetyVote_ResultSnapshots WHERE CampaignVersionID=? AND StageID=?',[$c['CurrentVersionID'],$stage]);$counts=db_row("SELECT (SELECT EligibleCount FROM SafetyVote_EligibilitySnapshots WHERE CampaignVersionID=? AND Status='frozen' LIMIT 1) eligible,(SELECT COUNT(*) FROM SafetyVote_Ballots WHERE CampaignVersionID=? AND Status='Accepted') ballots",[$c['CurrentVersionID'],$c['CurrentVersionID']]);db_execute("INSERT INTO SafetyVote_ResultSnapshots(CampaignID,CampaignVersionID,StageID,SnapshotNo,CalculationContract,Status,EligibleCount,ParticipationCount,AcceptedBallotCount,QuorumState,TieState,ReconciliationState,InputHash,ResultHash,CalculatedBy) VALUES(?,?,?,?,?,'Calculated',?,?,?,?,?,'balanced',?,?,?)",[$c['id'],$c['CurrentVersionID'],$stage,$n['no'],SV4_CONTRACT,(int)($counts['eligible']??0),$out['participationCount'],(int)($counts['ballots']??0),$out['quorumState'],$out['tieState'],$out['inputHash'],$out['resultHash'],sv_actor($u)]);$sid=(int)db()->lastInsertId();foreach($out['rows']as$r)db_execute("INSERT INTO SafetyVote_ResultRows(ResultSnapshotID,StageID,CandidateID,MetricKey,NumericValue,RankNo,ResultState,MetadataJson) VALUES(?,?,?,'combined_score',?,?,?,?)",[$sid,$stage,$r['candidateId'],$r['totalScore'],$r['rank'],$r['advanced']?'advanced':'not_advanced',json_encode(['juryScore'=>$r['juryScore'],'popularScore'=>$r['popularScore'],'judgeCount'=>$r['judgeCount']])]);sv4_event($u,'SAFETY_VOTE_RESULT_CALCULATE',(int)$c['id'],'SafetyVote_ResultSnapshot',$sid,'stage='.$stage,['resultHash'=>$out['resultHash']]);json_response(['success'=>true,'data'=>['id'=>$sid,'snapshotNo'=>(int)$n['no']]+$out],201);}
