 if($certify&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_CERTIFY');$b=json_body();$c=sv4_campaign((int)$certify['id']);$snap=db_row("SELECT * FROM SafetyVote_ResultSnapshots WHERE id=? AND CampaignID=? AND Status IN ('Frozen','Certified')",[(int)$certify['snapshotId'],(int)$certify['id']]);if(!$c||!$snap||$snap['ResultHash']!==($b['resultHash']??'')||!sv3_text($b['reason']??'',1000))json_response(['success'=>false,'code'=>'RESULT_HASH_CONFLICT'],409);if(!sv4_role($c,sv_actor($u),'certifier',(int)$snap['StageID']))json_response(['success'=>false,'code'=>'CAMPAIGN_ASSIGNMENT_REQUIRED'],403);try{$reason=sv3_text($b['reason'],1000);db_execute("INSERT INTO SafetyVote_Certifications(ResultSnapshotID,CertifierEmployeeID,CertificationRole,Decision,Reason,ResultHashSnapshot) VALUES(?,?,?,'certified',?,?)",[$snap['id'],sv_actor($u),'certifier',$reason,$snap['ResultHash']]);db_execute("UPDATE SafetyVote_ResultSnapshots SET Status='Certified' WHERE id=?",[$snap['id']]);sv4_event($u,'SAFETY_VOTE_RESULT_CERTIFY',(int)$certify['id'],'SafetyVote_ResultSnapshot',(int)$snap['id'],$reason,['resultHash'=>$snap['ResultHash']]);json_response(['success'=>true,'data'=>['id'=>(int)$snap['id'],'status'=>'Certified','resultHash'=>$snap['ResultHash']]],201);}catch(Throwable$e){json_response(['success'=>false,'code'=>'CERTIFICATION_DUPLICATE'],409);}}
 if($publish&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_CERTIFY');$n=db_row("SELECT rs.Status,COUNT(c.id) certifications FROM SafetyVote_ResultSnapshots rs LEFT JOIN SafetyVote_Certifications c ON c.ResultSnapshotID=rs.id AND c.Decision='certified' AND c.RevokedAt IS NULL WHERE rs.id=? AND rs.CampaignID=? GROUP BY rs.id",[(int)$publish['snapshotId'],(int)$publish['id']]);if(!$n||$n['Status']!=='Certified'||(int)$n['certifications']<1)json_response(['success'=>false,'code'=>'CERTIFICATION_REQUIRED'],422);db_execute("UPDATE SafetyVote_ResultSnapshots SET Status='Published' WHERE id=?",[(int)$publish['snapshotId']]);sv4_event($u,'SAFETY_VOTE_RESULT_PUBLISH',(int)$publish['id'],'SafetyVote_ResultSnapshot',(int)$publish['snapshotId'],'Published certified result');json_response(['success'=>true,'data'=>['id'=>(int)$publish['snapshotId'],'status'=>'Published']]);}
 if($advance&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');$b=json_body();$to=sv3_int($b['toStageId']??null);$snap=db_row("SELECT * FROM SafetyVote_ResultSnapshots WHERE id=? AND CampaignID=? AND Status IN ('Frozen','Certified','Published')",[(int)$advance['snapshotId'],(int)$advance['id']]);if(!$snap||!$to)json_response(['success'=>false,'code'=>'RESULT_STATE_CONFLICT'],409);$rows=db_rows("SELECT CandidateID FROM SafetyVote_ResultRows WHERE ResultSnapshotID=? AND ResultState='advanced' ORDER BY RankNo",[$snap['id']]);if(!$rows)json_response(['success'=>false,'code'=>'NO_ADVANCEMENT'],422);foreach($rows as$x)db_execute("INSERT INTO SafetyVote_StageAdvancements(CampaignVersionID,FromStageID,ToStageID,CandidateID,ResultSnapshotID,Decision,RuleHash,Reason,AdvancedBy) VALUES(?,?,?,?,?,'advanced',?,?,?) ON DUPLICATE KEY UPDATE Reason=VALUES(Reason)",[$snap['CampaignVersionID'],$snap['StageID'],$to,$x['CandidateID'],$snap['id'],$snap['ResultHash'],sv3_text($b['reason']??'',1000)?:null,sv_actor($u)]);sv4_event($u,'SAFETY_VOTE_STAGE_ADVANCE',(int)$advance['id'],'SafetyVote_ResultSnapshot',(int)$snap['id'],'to='.$to.'; candidates='.count($rows));json_response(['success'=>true,'data'=>['fromStageId'=>(int)$snap['StageID'],'toStageId'=>$to,'advancedCandidateIds'=>array_map('intval',array_column($rows,'CandidateID'))]]);}
